<script setup lang="ts">
import { reactive, ref } from 'vue'
import DataTable from './DataTable.vue'
import { api } from './api'
const table=ref<InstanceType<typeof DataTable>>(),error=ref(''),notice=ref(''),busy=ref(false),editing=ref(''),show=ref(false)
const form=reactive({label:'',username:'',password:''})
function edit(row?:Record<string,any>){editing.value=row?.id||'';Object.assign(form,{label:row?.label||'',username:row?.username||'',password:''});show.value=true}
async function save(){busy.value=true;error.value='';try{const body:Record<string,string>={...form};if(editing.value&&!form.password)delete body.password;await api(editing.value?`/credentials/${editing.value}`:'/credentials',editing.value?'PATCH':'POST',body);form.password='';show.value=false;notice.value='Credential saved';await table.value?.load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function remove(row:Record<string,any>){if(!confirm(`Delete credential "${row.label}"? Referenced credentials cannot be deleted.`))return;try{await api(`/credentials/${row.id}`,'DELETE');notice.value='Credential deleted';await table.value?.load()}catch(e){error.value=(e as Error).message}}
</script>
<template><div class="page-heading"><div><p class="eyebrow">ENCRYPTED LIBRARY</p><h1>Credentials<span class="accent">.</span></h1><p class="muted">Approved account pairs for explicitly scoped validation.</p></div><button @click="edit()">+ Add credential</button></div><p v-if="error" role="alert" class="error">{{error}}</p><p v-if="notice" role="status" class="notice">{{notice}}</p><section v-if="show" class="panel"><h2>{{editing?'Edit credential':'New credential'}}</h2><form @submit.prevent="save"><div class="form-grid"><label>Label<input v-model="form.label" required maxlength="200"></label><label>Username<input v-model="form.username" required maxlength="200" autocomplete="off"></label><label>{{editing?'New password (leave blank to retain)':'Password'}}<input v-model="form.password" type="password" :required="!editing" maxlength="1000" autocomplete="new-password"></label></div><div class="actions"><button :disabled="busy">Save credential</button><button type="button" class="subtle" @click="show=false;form.password=''">Cancel</button></div></form></section><DataTable ref="table" endpoint="/credentials" :columns="[{key:'label',label:'Label'},{key:'username',label:'Username'},{key:'secret',label:'Password'},{key:'created_at',label:'Created'},{key:'updated_at',label:'Updated'}]"><template #actions="{row}"><button class="subtle" @click="edit(row)">Edit</button><button class="danger subtle" @click="remove(row)">Delete</button></template></DataTable></template>
